def sum_hero_subset_power(nums):
    mod=1000000007;prefix=answer=0
    for maximum in sorted(nums):
        answer=(answer+maximum*maximum%mod*(maximum+prefix))%mod
        prefix=(2*prefix+maximum)%mod
    return answer

